import { isEmptyCollectionNode, isScalarNode } from './nodes.mjs';
import { renderScalar } from './scalar.mjs';
import { repeatText } from './text.mjs';

function renderKeySortText(key) {
  if (isScalarNode(key)) {
    return renderScalar(key);
  }
  if (key.kind === 'sequence') {
    return dumpSequence(key, 0);
  }
  return dumpMapping(key, 0);
}

function sortedEntries(entries) {
  return entries
    .slice()
    .sort((left, right) => {
      const leftText = renderKeySortText(left.key);
      const rightText = renderKeySortText(right.key);
      if (leftText < rightText) {
        return -1;
      }
      if (leftText > rightText) {
        return 1;
      }
      return 0;
    });
}

function mergePrefixed(prefix, rendered, childIndent) {
  const lines = rendered.split('\n');
  let result = `${prefix} ${lines[0].slice(childIndent)}`;
  let index = 1;
  while (index < lines.length) {
    result += `\n${lines[index]}`;
    index += 1;
  }
  return result;
}

function dumpSequence(node, indent) {
  if (node.items.length === 0) {
    return '[]';
  }

  const lines = [];
  let index = 0;

  while (index < node.items.length) {
    const item = node.items[index];
    const prefix = `${repeatText(' ', indent)}-`;

    if (isScalarNode(item) || isEmptyCollectionNode(item)) {
      lines.push(`${prefix} ${dumpNode(item, indent + 2)}`);
    } else if (item.kind === 'sequence') {
      lines.push(mergePrefixed(prefix, dumpSequence(item, indent + 2), indent + 2));
    } else {
      lines.push(mergePrefixed(prefix, dumpMapping(item, indent + 2), indent + 2));
    }

    index += 1;
  }

  return lines.join('\n');
}

function dumpMapping(node, indent) {
  if (node.entries.length === 0) {
    return '{}';
  }

  const lines = [];
  const entries = sortedEntries(node.entries);
  let index = 0;

  while (index < entries.length) {
    const entry = entries[index];
    const prefix = `${repeatText(' ', indent)}${renderScalar(entry.key)}:`;

    if (isScalarNode(entry.value) || isEmptyCollectionNode(entry.value)) {
      lines.push(`${prefix} ${dumpNode(entry.value, indent + 2)}`);
    } else if (entry.value.kind === 'sequence') {
      lines.push(prefix);
      lines.push(dumpSequence(entry.value, indent));
    } else {
      lines.push(prefix);
      lines.push(dumpMapping(entry.value, indent + 2));
    }

    index += 1;
  }

  return lines.join('\n');
}

function dumpNode(node, indent) {
  if (isScalarNode(node)) {
    return renderScalar(node);
  }
  if (node.kind === 'sequence') {
    return dumpSequence(node, indent);
  }
  return dumpMapping(node, indent);
}

export function dump(node) {
  return `${dumpNode(node, 0)}\n`;
}

