const parsed = parseCommandLine(process.argv);

if (parsed.kind === 'help') {
  process.stdout.write(`${parsed.text}\n`);
  process.exit(0);
}

if (parsed.kind === 'error') {
  process.stderr.write(`${parsed.text}\n`);
  process.exit(parsed.exitCode);
}

