export function createStringNode(value) {
  return { kind: 'string', value };
}

export function createNullNode() {
  return { kind: 'null' };
}

export function createBoolNode(value) {
  return { kind: 'bool', value: value ? true : false };
}

export function createIntNode(value) {
  return { kind: 'int', value };
}

export function createFloatNode(value) {
  return { kind: 'float', value };
}

export function createSequenceNode(items) {
  return { kind: 'sequence', items };
}

export function createMappingNode(entries) {
  return { kind: 'mapping', entries };
}

export function isScalarNode(node) {
  return (
    node.kind === 'string' ||
    node.kind === 'null' ||
    node.kind === 'bool' ||
    node.kind === 'int' ||
    node.kind === 'float'
  );
}

export function isEmptyCollectionNode(node) {
  return (
    (node.kind === 'sequence' && node.items.length === 0) ||
    (node.kind === 'mapping' && node.entries.length === 0)
  );
}

function scalarNumericValue(node) {
  if (node.kind === 'bool') {
    return node.value ? 1 : 0;
  }

  if (node.kind === 'int') {
    return Number(node.value);
  }

  if (node.kind === 'float') {
    if (node.value === '.nan') {
      return NaN;
    }
    if (node.value === '.inf') {
      return Infinity;
    }
    if (node.value === '-.inf') {
      return -Infinity;
    }
    return Number(node.value);
  }

  return null;
}

export function keysEqual(left, right) {
  if (left.kind === right.kind) {
    if (left.kind === 'null') {
      return true;
    }

    if (left.kind === 'string' || left.kind === 'int' || left.kind === 'float') {
      return left.value === right.value;
    }

    if (left.kind === 'bool') {
      return left.value === right.value;
    }
  }

  const leftNumeric = scalarNumericValue(left);
  const rightNumeric = scalarNumericValue(right);

  if (leftNumeric === null || rightNumeric === null) {
    return false;
  }

  if (leftNumeric !== leftNumeric || rightNumeric !== rightNumeric) {
    return false;
  }

  return leftNumeric === rightNumeric;
}

export function setMappingEntry(entries, key, value) {
  let index = 0;
  while (index < entries.length) {
    if (keysEqual(entries[index].key, key)) {
      entries[index].value = value;
      return;
    }
    index += 1;
  }
  entries.push({ key, value });
}
